using System;using System.IO;using System.Linq;using System.Collections;using UnityEngine;using UnityEngine.UI;
public static class NWHeavy {
 static NewWeaponCombat n;static int contacts,releases,blocked,waves;static string root;static CombatEnemy enemy;static void Trace(NewWeaponCombat.Trace t){if(t.stage=="contact"||t.stage=="wave-contact"){if(t.after<t.before)contacts++;}if(t.stage=="release")releases++;if(t.stage=="wave-blocked"||t.stage=="obstructed")blocked++;if(t.stage=="wave-spawn")waves++;File.AppendAllText(root+"/heavy-trace.jsonl",JsonUtility.ToJson(new Entry{stage=t.stage,a=t.a,b=t.b,before=t.before,after=t.after,radius=t.radius,time=t.time})+"\n");}[Serializable]class Entry{public string stage;public Vector3 a,b;public float before,after,radius,time;}
 static IEnumerator Setup(NWProbe p){yield return p.Wait(()=>UnityEngine.Object.FindObjectsByType<Button>().Any(b=>b.name=="训练装备架"),5);var h=CP05Training.Instance.Hero;UnityEngine.Object.FindObjectsByType<Button>().Single(b=>b.name=="训练装备架").onClick.Invoke();yield return null;yield return null;var loot=UnityEngine.Object.FindObjectsByType<LootPickup>().Single(x=>x.Gear?.type==GearType.Greatsword);p.Check("heavy-pickup",loot.PickUp(h.Inventory));var c=h.GetComponent<AdventureCombat>();p.Check("heavy-equip",c.Gear.SelectMain(loot.Gear));yield return new WaitForSeconds(.3f);n=c.NewWeapons;p.Check("heavy-model",n.Visual.Ready&&n.Visual.Right.parent.name=="handslot.r"&&n.Visual.Left==null);enemy=CP05Training.Instance.Enemies[0];enemy.enabled=false;CP05Training.Instance.Enemies[1].gameObject.SetActive(false);Move(enemy,h.transform.position+Vector3.forward*1.8f);h.transform.rotation=Quaternion.identity;h.cameraTransform.GetComponent<OrbitCamera>().enabled=false;h.cameraTransform.position=h.transform.position+new Vector3(0,3,-5);h.cameraTransform.LookAt(enemy.transform.position+Vector3.up);contacts=releases=blocked=waves=0;n.Observed+=Trace;PlayerInput.Focus(true);yield return null;yield return null;}
 static void Move(CombatEnemy e,Vector3 pos){var cc=e.GetComponent<CharacterController>();cc.enabled=false;e.transform.position=pos;cc.enabled=true;}
 static IEnumerator Restart(NWProbe p){var h=CP05Training.Instance.Hero;CP05Training.Instance.RequestRestart();yield return p.Wait(()=>CP05Training.Instance.Hero!=h&&!CP05Training.Instance.Restarting,6);yield return null;yield return null;}
 public static IEnumerator Run(NWProbe p){root=p.Root;yield return p.Wait(()=>CP05Training.Instance?.Hero!=null,15);yield return Setup(p);var h=n.Hero;var c=n.Combat;enemy.gameObject.AddComponent<BoxCollider>().center=Vector3.up;float before=enemy.Health.Current;p.Check("heavy-basic-request",c.Strike());yield return new WaitForSeconds(.2f);p.Check("heavy-windup-no-damage",enemy.Health.Current==before&&releases==0);yield return new WaitForSeconds(.45f);p.Check("heavy-basic-unique",contacts==1&&releases==1&&enemy.Health.Current<before);yield return Shot(p,"heavy-basic.png");
 yield return Restart(p);yield return Setup(p);h=n.Hero;c=n.Combat;before=enemy.Health.Current;p.Check("heavy-slam",c.UseSkill());p.Check("heavy-cooldown",!c.UseSkill());yield return new WaitForSeconds(.9f);p.Check("heavy-guardbreak-real-state",enemy.GetComponent<EnemyWeaponControl>()?.GuardBroken==true&&contacts==1&&enemy.Health.Current<before);yield return Shot(p,"heavy-slam.png");yield return new WaitForSeconds(.85f);p.Check("heavy-guardbreak-expires",!enemy.GetComponent<EnemyWeaponControl>().GuardBroken);
 yield return Restart(p);yield return Setup(p);h=n.Hero;c=n.Combat;n.Select(1);yield return null;yield return null;p.Check("wave-request",c.UseSkill());yield return new WaitForSeconds(1.1f);p.Check("wave-real-collision",waves==1&&contacts==1);yield return Shot(p,"heavy-wave.png");
 yield return Restart(p);yield return Setup(p);h=n.Hero;c=n.Combat;before=enemy.Health.Current;var wall=GameObject.CreatePrimitive(PrimitiveType.Cube);wall.transform.position=h.transform.position+new Vector3(0,1,.9f);wall.transform.localScale=new Vector3(4,3,.2f);n.Select(1);yield return null;yield return null;p.Check("wave-wall-request",c.UseSkill());yield return new WaitForSeconds(1.4f);p.Check("wave-wall-stops",blocked>0&&contacts==0&&enemy.Health.Current==before);
 yield return Restart(p);yield return Setup(p);h=n.Hero;c=n.Combat;Move(enemy,h.transform.position-Vector3.forward*1.6f);before=enemy.Health.Current;p.Check("heavy-back-request",c.Strike());yield return new WaitForSeconds(1.1f);p.Check("heavy-not-360",enemy.Health.Current==before&&contacts==0);
 yield return Restart(p);yield return Setup(p);h=n.Hero;c=n.Combat;p.Check("heavy-cancel-start",c.UseSkill());h.Inventory.SetOpen(true);yield return p.Wait(()=>false,.4f);p.Check("heavy-pause-cancel",releases==0&&!n.Busy);h.Inventory.SetOpen(false);yield return new WaitForSeconds(.8f);p.Check("heavy-no-resume-replay",releases==0&&c.SkillRemaining>0);
 }
 static IEnumerator Shot(NWProbe p,string name){yield return new WaitForEndOfFrame();var t=ScreenCapture.CaptureScreenshotAsTexture();File.WriteAllBytes(p.Root+"/"+name,t.EncodeToPNG());UnityEngine.Object.Destroy(t);}
}
